 egin{theorem_}\label{III:4-1bis}

\subsection{Scholie}\label{VI:1-9}
Soient $S_0$ un schéma séparé de type fini sur $\dF_q$, $G_0$ un groupe 
algébrique commutatif connexe sur $\dF_q$, $f_0:S_0	o G_0$ un morphisme et 
$\chi:G_0(\dF_q) 	o E_\lambda^	imes$. On a 
 egin{equation*}	ag{1.9.1}\label{VI:eq:1-9-1}
  \sum_{s\in S_0(\dF_q)} \chi f_0(s) = 	r(F^\ast,\h_c^ ullet(S,\sF(\chi,f_0))) 
\end{equation*}
et, pour tout entier $n\geqslant 1$
 egin{equation*}	ag{1.9.2}\label{VI:eq:1-9-2}
  \sum_{s\in S_0(\dF_{q^n})} \chi\circ N_{\dF_{q^n}/\dF_q} f_0(s) = 	r({F^\ast}^n, \h_c^ ullet\left(S,\sF(\chi,f_0))ight) 	ext{.}
\end{equation*}

Le cas le plus souvent considéré est celui où $k$ est la somme de $N+1$
copes de $\dF_q$; $\chi$ correspond alors à $(N+1)$ caractères
$\chi_0,\dots,\chi_N$ non tous triviaux de $\dF_q^	imes$, de produit égal à $1$.
Dans ce cas, une section du quotient $k^	imes/\dF_q^	imes$ de $k^	imes$
est l'ensemble des $(x_0,\dots,x_N)\in (k^	imes)^{N+1}$ avec $x_0=1$;
pour un tel $x$, la condition $	r(x)=0$ s'écrit $\sum_{i=1}^n x_i=-1$.
La somme de Jacobi s'écrit donc
 egin{equation*}	ag{4.14.2}\label{VI:eq:4-14-2}
  J(\chi) = (-1)^{N-1} \sum_{\substack{x_1,\dots,x_N\in \dF_q^	imes \ \sum x_i=-1}} \chi_1^{-1}(x_1)\cdots\chi_n^{-1}(x_n) 	ext{.}
\end{equation*}

On a entre sommes de Gauss et sommes de Jacobi l'identité suivante.
